const [a, b, c] = await Promise.all([
  gm.list_dir({ path: '/workspace/gm-new/src' }),
  gm.list_dir({ path: '/workspace/gmr/rust/src' }),
  gm.list_dir({ path: '/workspace/gmr/jit' }),
]);
return { gmSrc: a.output, gmrRust: b.output, gmrJit: c.output };

const [a, b] = await Promise.all([gm.list_dir({ path: '/workspace/gmr/jit/lib' }), gm.list_dir({ path: '/workspace/gmr/jit/verbs' })]);
const files = ['/workspace/gmr/jit/lib/search-paths.mjs'];
return { lib: a.output, verbs: b.output };

const names = ['code', 'exec', 'fs', 'git', 'net', 'review', 'rows', 'search'];
const reads = await Promise.all(names.map((n) => gm.read_file({ path: `/workspace/gmr/jit/verbs/${n}.mjs` })));
const out = {};
names.forEach((n, i) => {
  const lines = reads[i].output.split('\n');
  const hits = [];
  lines.forEach((l, j) => { if (/lock|mode:|name: '/.test(l)) hits.push(`${j + 1}: ${l.trim()}`); });
  out[n] = hits;
});
return out;

